const $=id=>document.getElementById(id),defaults={cash:65000,income:8000,expenses:4800,care:900,retirement:900,buffer:6,months:6,goal:"I want to care for my father while protecting my family's emergency savings.",notes:'',selected:'now',checks:[]};let p;try{p={...defaults,...JSON.parse(localStorage.getItem('futurelife-v1')||'{}')}}catch{p={...defaults}}const modes=['now','part','prepare'],names={now:'Take the break now',part:'Work part-time',prepare:'Prepare for 6 months'},colors=['#21685b','#b98632','#7e8eae'],money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),tasks=['Confirm leave, health coverage and employment benefits','Review care costs and emergency savings needs','Discuss the contribution gap and recovery plan with an advisor'];function save(){try{localStorage.setItem('futurelife-v1',JSON.stringify(p))}catch{}}
const fields=[['cash','Accessible savings ($)',0,10000000],['income','Monthly take-home income ($)',0,1000000],['expenses','Monthly living expenses ($)',1,1000000],['care','Additional monthly care costs ($)',0,1000000],['retirement','Monthly employee retirement contribution ($)',0,100000],['buffer','Desired emergency buffer (months)',1,24]];
fields.forEach(([key,title,min,max])=>{const d=document.createElement('div');d.innerHTML=`<label for="${key}">${title}</label><input type="number" id="${key}" min="${min}" max="${max}" step="${key==='buffer'?1:100}" value="${p[key]}">`;$('inputs').append(d);$(key).oninput=()=>{let n=Number($(key).value);if(!Number.isFinite(n))return;p[key]=Math.min(max,Math.max(min,n));save();render()};$(key).onchange=()=>{$(key).value=p[key]}});
$('months').value=p.months;$('goal').value=p.goal;$('notes').value=p.notes;['goal','notes'].forEach(key=>$(key).oninput=()=>{p[key]=$(key).value;save();if(key==='goal')brief()});$('months').oninput=()=>{p.months=+$('months').value;save();render()};document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{p.months=+b.dataset.month;$('months').value=p.months;save();render()});tasks.forEach((task,i)=>{let l=document.createElement('label');l.className='check';let c=document.createElement('input');c.type='checkbox';c.checked=p.checks.includes(i);c.onchange=()=>{p.checks=c.checked?[...p.checks,i]:p.checks.filter(x=>x!==i);save();brief()};l.append(c,document.createTextNode(task));$('checks').append(l)});
function results(){return Object.fromEntries(modes.map(m=>[m,simulate(p,m)]))}function render(){const r=results(),v=r[p.selected],floor=p.buffer*(p.expenses+p.care);$('duration').textContent=p.months;$('cards').replaceChildren();modes.forEach((m,i)=>{let b=document.createElement('button');b.className='card'+(p.selected===m?' selected':'');b.setAttribute('aria-pressed',p.selected===m);b.innerHTML=`<span style="color:${colors[i]}">${names[m]}</span><strong>${money(r[m].cash)}</strong><small>Ending savings · month ${r[m].months}<br>${m==='part'?'50% of take-home income retained':m==='prepare'?'6 months of normal income first':'No take-home income during break'}</small>`;b.onclick=()=>{p.selected=m;save();render()};$('cards').append(b)});$('metrics').innerHTML=`<div class="metric"><span class="eyebrow">Ending buffer</span><b>${v.buffer.toFixed(1)} months</b><small>of living + care expenses</small></div><div class="metric"><span class="eyebrow">Contribution gap</span><b>${money(v.missed)}</b><small>employee contributions only</small></div><div class="metric"><span class="eyebrow">Emergency floor</span><b>${money(floor)}</b><small>your ${p.buffer}-month target</small></div>`;$('insight').textContent=(v.cash<0?`This scenario has an unfunded cash gap of ${money(-v.cash)}.`:v.cash<floor?`Ending savings fall ${money(floor-v.cash)} below your chosen emergency floor.`:`Ending savings remain ${money(v.cash-floor)} above your chosen emergency floor.`)+' Review benefits, affordability and retirement assumptions with an advisor. This is a scenario explanation, not a recommendation.';const vals=Object.values(r).flatMap(x=>x.series),lo=Math.min(0,...vals),hi=Math.max(floor,...vals,1),n=p.months+6,X=m=>60+m/n*680,Y=v=>195-(v-lo)/(hi-lo)*165;let svg='';for(let i=0;i<4;i++){let v=lo+(hi-lo)*i/3;svg+=`<line x1="60" y1="${Y(v)}" x2="740" y2="${Y(v)}" stroke="#e2e9df"/><text x="2" y="${Y(v)+4}" font-size="11" fill="#657970">${Math.round(v/1000)}k</text>`}svg+=`<line x1="60" x2="740" y1="${Y(floor)}" y2="${Y(floor)}" stroke="#a18756" stroke-dasharray="5 5"/>`;modes.forEach((m,i)=>svg+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="${p.selected===m?4:2}" points="${r[m].series.map((v,j)=>X(j)+','+Y(v)).join(' ')}"/>`);[0,Math.round(n/2),n].forEach(m=>svg+=`<text x="${X(m)}" y="225" font-size="11" fill="#657970">Month ${m}</text>`);$('chart').setAttribute('viewBox','0 0 780 240');$('chart').innerHTML=svg;brief()}
function brief(){const v=simulate(p,p.selected);$('brief').textContent=`MAYA · AGE 47 · SYNTHETIC HOUSEHOLD\n\nPriority: ${p.goal}\nSelected rehearsal: ${names[p.selected]}\nCareer break: ${p.months} months | Scenario horizon: ${v.months} months\n\nINPUTS — participant-editable sample values\nAccessible savings: ${money(p.cash)}\nMonthly take-home income: ${money(p.income)}\nLiving expenses: ${money(p.expenses)} / month\nAdditional care costs: ${money(p.care)} / break month\nEmployee retirement contributions: ${money(p.retirement)} / month\nEmergency floor: ${p.buffer} months\n\nILLUSTRATIVE RESULTS\nEnding accessible savings: ${money(v.cash)}\nEnding expense buffer: ${v.buffer.toFixed(1)} months\nEmployee contribution gap: ${money(v.missed)}\n\nPREPARATION PROGRESS\n${tasks.map((t,i)=>(p.checks.includes(i)?'[Reviewed] ':'[Open] ')+t).join('\n')}\n\nQUESTIONS TO VALIDATE\nWhat happens to employer benefits and match?\nAre care costs and household income complete?\nWhat contribution recovery plan is affordable?\n\nMODEL LIMITS\nNo returns, taxes, inflation, employer match, benefits changes or penalties. Part-time assumes 50% income and contributions. Prepare assumes 6 months of normal surplus before the break. No recommendation or transaction has been made.`}
function view(name){$('studio').classList.toggle('hidden',name!=='studio');$('advisor').classList.toggle('hidden',name!=='advisor');$('studioTab').classList.toggle('active',name==='studio');$('advisorTab').classList.toggle('active',name==='advisor');brief();window.scrollTo(0,0)}$('studioTab').onclick=$('back').onclick=()=>view('studio');$('advisorTab').onclick=$('prepare').onclick=()=>view('advisor');$('reset').onclick=()=>{localStorage.removeItem('futurelife-v1');location.reload()};$('download').onclick=()=>{if(!$('consent').checked){$('status').textContent='Please review the brief and select the confirmation above.';return}let blob=new Blob([$('brief').textContent+'\n\nADDITIONAL QUESTIONS\n'+p.notes],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='FutureLife_Advisor_Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Discussion brief downloaded. Nothing was sent to an advisor.'};render();
